#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string removeDuplicateLetters(string s) {
        vector<int> last_occ(26, 0);
        for (int i = 0; i < (int)s.size(); i++) last_occ[s[i] - 'a'] = i;
        string res = "";
        vector<bool> seen(26, false);
        for (int i = 0; i < (int)s.size(); i++) {
            int idx = s[i] - 'a';
            if (!seen[idx]) {
                while (!res.empty() && res.back() > s[i] && last_occ[res.back() - 'a'] > i) {
                    seen[res.back() - 'a'] = false;
                    res.pop_back();
                }
                seen[idx] = true;
                res += s[i];
            }
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String removeDuplicateLetters(String s) {
        int[] lastOcc = new int[26];
        for (int i = 0; i < s.length(); i++) lastOcc[s.charAt(i) - 'a'] = i;
        boolean[] seen = new boolean[26];
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int idx = c - 'a';
            if (!seen[idx]) {
                while (sb.length() > 0 && sb.charAt(sb.length() - 1) > c && lastOcc[sb.charAt(sb.length() - 1) - 'a'] > i) {
                    seen[sb.charAt(sb.length() - 1) - 'a'] = false;
                    sb.deleteCharAt(sb.length() - 1);
                }
                seen[idx] = true;
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

var removeDuplicateLetters = function(s) {
    const lastOcc = {};
    for (let i = 0; i < s.length; i++) lastOcc[s[i]] = i;
    const stack = [];
    const seen = new Set();
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (!seen.has(c)) {
            while (stack.length > 0 && stack[stack.length - 1] > c && lastOcc[stack[stack.length - 1]] > i) {
                seen.delete(stack.pop());
            }
            seen.add(c);
            stack.push(c);
        }
    }
    return stack.join('');
};
